    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          col=grid[r][c]; q=deque([(r,c)]); seen.add((r,c)); pts=[]
          while q:
            y,x=q.popleft(); pts.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              p=(y+dy,x+dx)
              if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==col:
                seen.add(p); q.append(p)
          objs.append([col,pts])
    # Each object slides right until the edge or another object blocks it.
    objs.sort(key=lambda z:max(x for y,x in z[1]),reverse=True)
    settled=[]
    for col,pts in objs:
      pts=[list(p) for p in pts]
      while True:
        nxt={(y,x+1) for y,x in pts}
