        if any((y,x) in nxt for other in settled for oy,x in other[1] for y in [oy]): break
        pts=[[y,x+1] for y,x in pts]
      settled.append((col,pts))
    out=[[0]*w for _ in range(h)]
    for col,pts in settled:
